export function RangeToggle({ value = "7d", onChange = () => {}, options = ["7d", "14d", "30d"] }: {
  value?: string;
  onChange?: (v: string) => void;
  options?: string[];
}) {
  return (
    <div className="seg">
      {options.map(o => (
        <button key={o} className={o === value ? "on" : ""} onClick={() => onChange(o)}>{o}</button>
      ))}
    </div>
  );
}
